mapper.select:
 SELECT

 FROM zdata_trail_tracks t
 WHERE 1 = 1
  and t.uuid = #{uuid}
  and t.type = #{type}
  and t.point_count = #{pointCount}
  and t.plate_key = #{plateKey}
  and t.enter_time = #{enterTime}
  and t.exit_time = #{exitTime}
  and t.trail_points = #{trailPoints}
  and t.plate_key = #{carNo} 
 and t.enter_time >= STR_TO_DATE(#{applyTime1},'%Y-%m-%d')
 and t.enter_time < date_add(STR_TO_DATE(#{applyTime2},'%Y-%m-%d'), interval 1 day) 
order by t.enter_time desc

select

from zdata_trail_tracks t
where t.uuid = #{uuid}

select t.uuid, t.type, t.point_count, t.plate_key, t.enter_time, t.exit_time, t.create_time, t.enter_locationcode, t.exit_locationcode, t.track_josn, t.enaxlecount, t.entolllaneid, t.entollstationid, t.entollstationname, t.envehicleclass, t.envehicleid, t.envehicletype, t.enweight, t.extolllaneid, t.extollstationid, t.extollstationname, t.exvehicleclass, t.exvehicleid, t.exvehicletype, t.exweight, t.start_lon, t.strat_lat, t.end_lon, t.end_lat from zdata_trail_tracks t where 1=1 and t.plate_key = #{carNo} and t.plate_key like concat('%', #{plateKey}, '%') and t.enter_time >= STR_TO_DATE(#{applyTime1},'%Y-%m-%d') and t.enter_time < date_add(STR_TO_DATE(#{applyTime2},'%Y-%m-%d'), interval 1 day) and t.entollstationid = #{entollstationid}
and uuid in
#{uuid}
order by t.enter_time desc

